                + "  m_ObjectHideFlags: 0\n  m_CorrespondingSourceObject: {fileID: 0}\n"
                + "  m_PrefabInstance: {fileID: 0}\n  m_PrefabAsset: {fileID: 0}\n"
                + "  m_GameObject: {fileID: " + gameObjectId + "}\n  m_Enabled: 1\n  m_EditorHideFlags: 0\n"
                + "  m_Script: {fileID: 11500000, guid: " + Legacy + ", type: 3}\n"
                + "  m_Name: \n  m_EditorClassIdentifier: " + identifier + "\n" + fields;
            File.WriteAllText(path, yaml);
            return path;
        }

