                .Replace("  m_Script:", "  # 中文名称与 emoji 🙂 位于脚本 GUID 之前\n  m_Script:")
                .Replace("\n", "\r\n");
            byte[] original = Encoding.UTF8.GetPreamble().Concat(Encoding.UTF8.GetBytes(text)).ToArray();
            File.WriteAllBytes(path, original);
            byte[] metadata = File.ReadAllBytes(path + ".meta");
            var plan = MigrationEngine.Scan(new[] { path });
            var entry = plan.Entries.Single();
            Assert.That(entry.Status, Is.EqualTo(MigrationStatus.Ready));
            var result = MigrationEngine.Apply(plan);
            Assert.That(result.RepairedComponents, Is.EqualTo(1));
            Assert.That(result.ChangedAssets, Is.EqualTo(new[] { path }));
            string expected = text.Replace("m_Script: {fileID: 11500000, guid: " + Legacy,
                "m_Script: {fileID: 11500000, guid: " + entry.TargetGuid);
