            Assert.That(File.ReadAllBytes(path + ".meta"), Is.EqualTo(metadata));
            Assert.That(File.ReadAllBytes(Path.Combine(result.BackupDirectory, path)), Is.EqualTo(original));
            Assert.That(File.ReadAllBytes(Path.Combine(result.BackupDirectory, path + ".meta")), Is.EqualTo(metadata));
            Assert.That(File.Exists(Path.Combine(result.BackupDirectory, "report.json")), Is.True);
            Assert.That(MigrationEngine.Apply(MigrationEngine.Scan(new[] { path })).RepairedComponents, Is.Zero);
        }

